const email = $json;
const subject = String(email.subject ?? email.headers?.subject ?? '');
const titleMatch = subject.match(/^Notes:\s*[“\"]?(Sprint Planning|Sprint Estimating)[”\"]?\b/i);
const dateMatch = subject.match(/(\d{1,2}[/-]\d{1,2}[/-]\d{2,4}|\d{4}-\d{2}-\d{2})/);
const html = String(email.textHtml ?? email.textPlain ?? email.snippet ?? '');
const docMatch = html.match(/docs\.google\.com\/document\/d\/([a-zA-Z0-9_-]+)/);
const docId = docMatch?.[1] ?? email.docId ?? null;
const receivedAt = email.internalDate ?? email.date ?? new Date().toISOString();
return [{ json: {
  subject,
  title: titleMatch?.[1] ?? null,
  meetingDate: dateMatch?.[1] ?? receivedAt,
  docId,
  docUrl: docId ? `https://docs.google.com/document/d/${docId}/edit` : null,
  emailId: email.id ?? null,
  sourceEmail: email,
} }];

const identity = $('Extract Meeting Identity').item.json;
const events = $input.all().map((item) => item.json);
const allowed = new Set([
  $env.MODUS_SPRINT_PLANNING_SERIES_ID,
  $env.MODUS_SPRINT_ESTIMATING_SERIES_ID,
].filter(Boolean));
const event = events.find((candidate) => {
  const seriesId = candidate.recurringEventId ?? candidate.iCalUID ?? candidate.iCalUid;
  return seriesId && allowed.has(seriesId);
});
const staticData = $getWorkflowStaticData('global');
staticData.meetingDocs = staticData.meetingDocs || {};
const prior = identity.docId ? staticData.meetingDocs[identity.docId] : null;
const accepted = Boolean(identity.title && identity.docId && event && !prior);
if (identity.docId && prior) {
  return [{ json: { ...identity, route: 'duplicate', reason: `Doc ID already processed with status ${prior.status}.` } }];
}
if (!accepted) {
  return [{ json: { ...identity, route: 'ignore', reason: 'Title, Doc ID, or Modus calendar series allowlist did not match.' } }];
}
staticData.meetingDocs[identity.docId] = { status: 'processing', startedAt: Date.now(), title: identity.title };
return [{ json: { ...identity, route: 'accept', calendarEvent: event } }];

const identity = $('Apply Ceremony and Idempotency Gate').item.json;
const body = $json.body ?? $json;
const text = [];
for (const content of body.body?.content ?? []) {
  for (const element of content.paragraph?.elements ?? []) {
    if (element.textRun?.content) text.push(element.textRun.content);
  }
}
return [{ json: { ...identity, meetingText: text.join('') } }];

const identity = $('Normalize Complete Notes').item.json;
const raw = $json.output ?? $json.text ?? $json.response ?? '{}';
let classification;
try {
  classification = JSON.parse(String(raw).replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim());
} catch (error) {
  classification = { items: [], completeness: { extracted: 0, classified: 0 }, parseError: String(error) };
}
const items = Array.isArray(classification.items) ? classification.items : [];
const staticData = $getWorkflowStaticData('global');
const reviewId = `meeting-${identity.docId}-${Date.now()}`;
staticData.meetingDocs[identity.docId] = {
  status: 'reviewed',
  reviewId,
  updatedAt: Date.now(),
  items,
  docUrl: identity.docUrl,
  title: identity.title,
};
const labels = {
  'repo-work': 'Repository work',
  'design-work': 'Design work',
  'process/meta': 'Process / meta (no issue)',
  'decision-record': 'Decision record (existing issue)',
  'already-tracked': 'Already tracked',
};
const sections = Object.keys(labels).map((classificationName) => {
  const group = items.filter((item) => item.classification === classificationName);
  if (!group.length) return null;
  const widgets = group.map((item) => ({ selectionInput: { name: 'itemIds', type: 'CHECK_BOX', items: [{ text: `[${item.itemId}] ${item.rawText} — ${item.reason}`, value: item.itemId, selected: Boolean(item.createEligible && (classificationName === 'repo-work' || classificationName === 'design-work')) }] } }));
  return { header: labels[classificationName], widgets };
}).filter(Boolean);
sections.push({ widgets: [{ textParagraph: { text: `Completeness: ${items.length} extracted and ${items.length} classified. Every item is displayed.\nDoc: <a href=\"${identity.docUrl}\">open notes</a>` } }, { buttonList: { buttons: [{ text: 'Create selected drafts', onClick: { action: { actionMethodName: 'meeting_create_selected', parameters: [{ key: 'reviewId', value: reviewId }] } } }, { text: 'Discard review', onClick: { action: { actionMethodName: 'meeting_discard', parameters: [{ key: 'reviewId', value: reviewId }] } } }] } }] });
return [{ json: { reviewId, docId: identity.docId, reviewCard: { cardsV2: [{ cardId: reviewId, card: { header: { title: `${identity.title} notes review`, subtitle: 'Human selection required' }, sections } }] } } }];

const event = $json.body ?? $json;
const action = event.action ?? event.common?.invokedFunction ?? {};
const parameters = Object.fromEntries((action.parameters ?? []).map((p) => [p.key, p.value]));
const selected = event.common?.formInputs?.itemIds?.stringInputs?.value ?? event.action?.formInputs?.itemIds?.stringInputs?.value ?? [];
const reviewId = parameters.reviewId;
const staticData = $getWorkflowStaticData('global');
const review = Object.values(staticData.meetingDocs || {}).find((entry) => entry.reviewId === reviewId);
if (!review) throw new Error('Review not found or expired.');
if (action.actionMethodName === 'meeting_discard') {
  review.status = 'discarded';
  return [{ json: { route: 'discard', reviewId } }];
}
if (action.actionMethodName !== 'meeting_create_selected') {
  return [{ json: { route: 'invalid', reviewId } }];
}
const selectedSet = new Set(selected);
const candidates = review.items.filter((item) => selectedSet.has(item.itemId) && ['repo-work', 'design-work'].includes(item.classification));
return candidates.map((item) => ({ json: { route: 'create', reviewId, docUrl: review.docUrl, item } }));
